insert into public.government_schemes (
 slug,title_en,title_ur,summary_en,summary_ur,government_scope,category,benefit_type,benefit_details,eligibility_text,required_documents,application_steps,fees_and_repayment,official_apply_url,source_name,source_url,source_document_url,intake_status,application_open_at,deadline_at,status,published_at,verified_at,next_review_at
) values
('apni-chhat-apna-ghar','Apni Chhat Apna Ghar','اپنی چھت اپنا گھر','Punjab Government housing programme for eligible low-income households. The official programme page describes eligibility and a registration route; the current intake window and available options must be checked on the official portal.','اہل کم آمدن گھرانوں کے لیے حکومتِ پنجاب کا رہائشی پروگرام۔ سرکاری پروگرام صفحہ اہلیت اور رجسٹریشن کا طریقہ بتاتا ہے؛ موجودہ درخواستوں کی دستیابی سرکاری پورٹل سے ضرور چیک کریں۔','punjab','housing','housing','The programme aims to expand access to affordable housing across Punjab. The official page describes housing construction and development routes. Do not assume a particular loan amount, quota or current application window without checking the latest official notice.','The official page lists Punjab permanent residence by CNIC (applicant or a family member), sole ownership and possession of a residential plot up to 5 marla in urban areas or 10 marla in rural areas, and restrictions relating to criminal record and bank/financial-institution loan default. Check the live portal for the exact current conditions and the route that applies to you.',ARRAY['Valid CNIC and Punjab residence information','Official land ownership / possession details if required by the selected programme route','Any additional documents requested only by the official ACAG portal'],'Open the official ACAG portal and read the current registration instructions. Confirm that registration is accepting applications before preparing or submitting information. Hello Sadiqabad does not collect applications.','No current programme fee, financing amount or repayment terms are confirmed in this public listing. Read the latest official terms before proceeding.','https://acag.punjab.gov.pk/','Punjab Government — Special Monitoring Unit','https://smu.punjab.gov.pk/apni-chat-apna-ghar-program','https://smu.punjab.gov.pk/apni-chat-apna-ghar-program','unconfirmed',NULL,NULL,'published',now(),now(),now()+interval '7 days'),
('cm-punjab-asaan-karobar-card','CM Punjab Asaan Karobar Card','وزیراعلیٰ پنجاب آسان کاروبار کارڈ','Punjab SME financing programme offering eligible entrepreneurs a digital card facility of up to PKR 1 million. The programme is listed by PSIC; the current fresh-application intake must be confirmed through official channels.','اہل کاروباری افراد کے لیے پنجاب کا ڈیجیٹل کارڈ فنانسنگ پروگرام، جس میں ایک ملین روپے تک سہولت بیان کی گئی ہے۔ PSIC اسے اپنے پروگرامز میں شامل کرتا ہے، تاہم نئی درخواستوں کی موجودہ دستیابی پہلے تصدیق کریں۔','punjab','business_finance','loan','PSIC describes a three-year digital SME-card financing facility of up to PKR 1,000,000, with a three-month grace period followed by 33 monthly instalments. Borrower markup is stated as 0% and subsidised by the Government of Punjab. This is repayable financing, not a grant.','The official PSIC page lists age 21–57, Pakistani nationality and Punjab residence according to valid CNIC, existing or prospective business located in Punjab, valid CNIC, and a mobile number registered in the applicant’s own name. Confirm all current conditions and bank checks with PSIC / Bank of Punjab.',ARRAY['Valid CNIC','Mobile number registered in the applicant’s own name','Business location and business details in Punjab','Any additional documents requested by the official bank or application channel'],'Read the PSIC scheme page and the official SMU programme page. The SMU page links to the government application website. Confirm that new applications are currently being accepted before submitting an application.','PSIC lists a PKR 500 processing fee and annual card fee of PKR 25,000 plus FED. Loan tenure is three years, with three months grace and 33 monthly instalments. Borrower markup is described as 0%; fees still apply. Confirm the latest charges before applying.','https://akc.punjab.gov.pk/cmpunjabfinance','Punjab Small Industries Corporation (PSIC) / Punjab Government SMU','https://psic.punjab.gov.pk/node/177','https://smu.punjab.gov.pk/cm-punjab-asaan-karobar-card','unconfirmed',NULL,NULL,'published',now(),now(),now()+interval '7 days'),
('prime-minister-youth-business-agriculture-loan','Prime Minister’s Youth Business & Agriculture Loan Scheme','وزیراعظم یوتھ بزنس اینڈ ایگریکلچر لون اسکیم','Federal Government loan programme for eligible Pakistani residents with entrepreneurial potential. The official portal shows three loan tiers, while a separate federal announcement dated 10 November 2026 announced a new fourth tier; the application portal must be checked for implementation of the new tier.','کاروباری صلاحیت رکھنے والے اہل پاکستانی شہریوں کے لیے وفاقی قرضہ پروگرام۔ سرکاری پورٹل پر تین قرضہ درجات درج ہیں، جبکہ 10 نومبر 2026 کے وفاقی اعلان میں چوتھے درجے کا ذکر ہے؛ نئے درجے کے اطلاق کی تصدیق درخواست پورٹل سے کریں۔','federal','business_finance','loan','The official portal currently displays three tiers: up to PKR 500,000 at 0% markup; above PKR 500,000 up to PKR 1.5 million at 5%; and above PKR 1.5 million up to PKR 7.5 million at 7%. A PID announcement dated 10 November 2026 announced a new Tier 4 above PKR 7.5 million up to PKR 25 million at 8% markup for up to eight years. The new tier is not yet reflected on the portal page reviewed; confirm with the official programme / bank before relying on it. This is repayable financing, not a grant.','The official portal lists Pakistani residents aged 21–45 with entrepreneurial potential; the lower age limit is 18 for IT / e-commerce businesses. Check the current official form and bank criteria before applying. Government employees and non-residents should review the programme’s official exclusions.',ARRAY['Passport-size photograph','CNIC front and back copies (submit only on the official portal)','Latest educational certificate, if applicable','Experience certificate, if applicable','Business licence / chamber or trade-body registration, if applicable','NTN information where applicable','Electricity bill consumer ID for current address and business address, if applicable','Vehicle registration and two non-blood-relative references where requested','Business income, expenses and feasibility information as requested by the official form'],'Applications are submitted online through the official PMYP application form. The currently reviewed portal page still displays the first three tiers; check the official portal or participating bank for implementation details of the Tier 4 announced in November 2026. Never upload identity or supporting documents to Hello Sadiqabad or share them in chat.','Portal tiers: 0% markup up to PKR 500,000; 5% above PKR 500,000 up to PKR 1.5 million; 7% above PKR 1.5 million up to PKR 7.5 million. PID announced a fourth tier above PKR 7.5 million up to PKR 25 million at 8%, up to eight years. Confirm current form, fees, tenor and bank conditions before applying.','https://pmyp.gov.pk/bankform/newapplicantform','Prime Minister’s Youth Programme / Press Information Department — Government of Pakistan','https://pmybals.pmyp.gov.pk/','https://pid.gov.pk/site/press_detail/34717','unconfirmed',NULL,NULL,'published',now(),now(),now()+interval '7 days'),
('benazir-kafaalat-programme','Benazir Kafaalat Programme','بینظیر کفالت پروگرام','Federal social-protection cash assistance for eligible families assessed through BISP’s official registry and eligibility process. Current payment amount and household eligibility are not stated here; check the official 8171 service and latest BISP notices.','اہل گھرانوں کے لیے وفاقی سماجی تحفظ اور مالی معاونت کا پروگرام، جس کی اہلیت BISP کے سرکاری رجسٹری نظام کے ذریعے طے ہوتی ہے۔ موجودہ قسط اور اہلیت کی تصدیق صرف سرکاری 8171 سروس اور BISP اعلانات سے کریں۔','federal','social_protection','cash_transfer','Eligible beneficiary households may receive cash assistance through the Benazir Kafaalat programme. The current payment amount is intentionally not stated because a current dated official payment notification was not confirmed during this review.','Eligibility is determined by BISP through its official registry and assessment process. A status check does not guarantee enrolment or payment. Use only BISP’s official 8171 service and follow instructions from an official BISP Tehsil Office.',ARRAY['Do not send documents to Hello Sadiqabad. If BISP requests identity information, provide it only through its official 8171 channel or an official BISP registration desk.'],'Check your status only through https://8171.pass.gov.pk or the official 8171 SMS service. If the official BISP process directs you to update or complete a survey, visit the relevant official BISP Tehsil registration desk. Never pay an agent for a survey.','BISP states that the dynamic survey is free and 8171 is its only official SMS number. Do not pay registration agents, trust other SMS numbers or rely on old stipend amounts.','https://8171.pass.gov.pk/','Benazir Income Support Programme — Government of Pakistan','https://www.bisp.gov.pk/','https://www.bisp.gov.pk/NewsDetail/M2MzZDg0ZjctYjBkMS00YzQ1LTkwMjQtMmVhZWFiZDgyZmI0','unconfirmed',NULL,NULL,'published',now(),now(),now()+interval '7 days'),
('benazir-hunarmand-programme','Benazir Hunarmand Programme','بینظیر ہنرمند پروگرام','Federal skills and vocational-training programme for eligible people registered in the BISP Dynamic Registry. The official portal says registration is reviewed and selection is not automatic; check current district and course availability before travelling.','BISP ڈائنامک رجسٹری میں رجسٹرڈ اہل افراد کے لیے وفاقی ہنر اور پیشہ ورانہ تربیت کا پروگرام۔ سرکاری پورٹل کے مطابق رجسٹریشن کے بعد جانچ ہوتی ہے اور انتخاب خودکار نہیں؛ سفر سے پہلے ضلع اور کورس کی دستیابی چیک کریں۔','federal','skills','training','The programme provides access to skills and vocational-training opportunities for applicants selected through the official review process. Course availability, training locations and selection depend on the programme’s current arrangements.','The official portal states that applicants must be registered in the BISP Dynamic Registry, have at least Matric education, be aged 18–40, and only one person per family may register. The portal does not establish that a course or seat is currently available in Sadiqabad; confirm district coverage before travelling. Registration does not guarantee selection.',ARRAY['Original and valid CNIC and active mobile number for official in-person registration if required','Matric or higher education information','Any additional information requested only by the official programme portal or Tehsil Office'],'Register only through the official Benazir Hunarmand portal or follow its instructions for the nearest Tehsil Office. The portal says applications are reviewed and eligible applicants are selected; check whether registration and courses are currently available in your district.','No application fee or stipend amount is confirmed on the official portal page reviewed. Do not pay agents. Confirm any course-related cost or allowance only through BISP.','https://hunarmand.bisp.gov.pk/','Benazir Income Support Programme — Benazir Hunarmand Portal','https://hunarmand.bisp.gov.pk/','https://hunarmand.bisp.gov.pk/','unconfirmed',NULL,NULL,'published',now(),now(),now()+interval '7 days')
on conflict (slug) do update set
 title_en=excluded.title_en,title_ur=excluded.title_ur,summary_en=excluded.summary_en,summary_ur=excluded.summary_ur,government_scope=excluded.government_scope,
 category=excluded.category,benefit_type=excluded.benefit_type,benefit_details=excluded.benefit_details,eligibility_text=excluded.eligibility_text,
 required_documents=excluded.required_documents,application_steps=excluded.application_steps,fees_and_repayment=excluded.fees_and_repayment,
 official_apply_url=excluded.official_apply_url,source_name=excluded.source_name,source_url=excluded.source_url,source_document_url=excluded.source_document_url,
 intake_status=excluded.intake_status,application_open_at=excluded.application_open_at,deadline_at=excluded.deadline_at,status=excluded.status,
 published_at=coalesce(public.government_schemes.published_at,excluded.published_at),verified_at=excluded.verified_at,next_review_at=excluded.next_review_at,updated_at=now();